CREATE FUNCTION public.validate_enquiry() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; BEGIN IF NEW.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Invalid email'; END IF; IF jsonb_typeof(NEW.items) <> 'array' OR jsonb_array_length(NEW.items)>100 THEN RAISE EXCEPTION 'Invalid requirement items'; END IF; IF NEW.kind='bulk' AND jsonb_array_length(NEW.items)=0 THEN RAISE EXCEPTION 'Add a product'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(NEW.items) LOOP IF jsonb_typeof(item->'quantity') <> 'number' OR (item->>'quantity')::numeric <> trunc((item->>'quantity')::numeric) OR (item->>'quantity')::numeric NOT BETWEEN 1 AND 100000 OR NOT EXISTS(SELECT 1 FROM public.products WHERE id=item->>'product_id' AND published) THEN RAISE EXCEPTION 'Invalid product or quantity'; END IF; END LOOP; IF TG_OP='INSERT' AND NOT public.claim_submission('enquiry:'||NEW.user_id::text) THEN RAISE EXCEPTION 'Please wait a minute before submitting another enquiry'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_enquiry() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER apex_validate_enquiry BEFORE INSERT OR UPDATE ON public.enquiries FOR EACH ROW EXECUTE FUNCTION public.validate_enquiry();
CREATE TABLE public.inventory_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id text REFERENCES public.products(id) ON DELETE SET NULL,sku text NOT NULL,previous_stock integer,new_stock integer,actor_id uuid,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.inventory_transactions TO authenticated; GRANT ALL ON public.inventory_transactions TO service_role; ALTER TABLE public.inventory_transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY inventory_admin_read ON public.inventory_transactions FOR SELECT TO authenticated USING(public.can_manage('product')); CREATE INDEX inventory_product_idx ON public.inventory_transactions(product_id);
CREATE FUNCTION public.record_inventory_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.stock IS NOT NULL THEN INSERT INTO public.inventory_transactions(product_id,sku,previous_stock,new_stock,actor_id) VALUES(NEW.id,NEW.sku,NULL,NEW.stock,auth.uid()); END IF; ELSIF NEW.stock IS DISTINCT FROM OLD.stock THEN INSERT INTO public.inventory_transactions(product_id,sku,previous_stock,new_stock,actor_id) VALUES(NEW.id,NEW.sku,OLD.stock,NEW.stock,auth.uid()); END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.record_inventory_change() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER apex_inventory_history AFTER INSERT OR UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.record_inventory_change();